-- One-off upload: Narok TaifaCare Q3 2025 - "Narok County — TaifaCare Training - CHPs/CHAs & SCHMT" -
-- 1,657 CHP payments, KES 1,797,000, paid 29 September 2025 (file "Narok TaifaCare Q3 2025 -
-- Upload Ready.xlsx", from source "Narok TaifaCare Q3 2025 Upload.xlsx", sheet "Narok CHPs").
-- Uploaded AS IS on the user's instruction (28 Sep 2026):
--   * Timothy Koitumet (KES 1,000) has no phone number - added blank and FLAGGED "Missing phone number".
--   * Janet Nashipai (+254702613402) appears twice with different amounts (KES 1,000 and 2,000) -
--     both added, each noted.
--   * Training dates are as in the file (2024-10-02 to 2024-10-02, 1 day) - the file's own note says to confirm them.
-- One event per sub-county venue (as the app's importer does), 9 new venues:
--   Narok Central Sub-County      212 payments  KES   230,000
--   Narok County                    2 payments  KES     8,000
--   Narok East Sub-County         310 payments  KES   331,000
--   Narok North Sub-County         97 payments  KES   105,000
--   Narok South Sub-County        306 payments  KES   330,000
--   Narok West Sub-County         188 payments  KES   202,000
--   Transmara East Sub-County     263 payments  KES   275,000
--   Transmara South Sub-County    134 payments  KES   148,000
--   Transmara West Sub-County     145 payments  KES   168,000
-- Checked on the live DB before writing: no Narok events or venues exist, and none of these phones
-- was paid in Sep-Oct 2025. Payment date is the TRUE date, so these rows must be EXCLUDED from the
-- later +1 day importer-bug backfill - they are listed in perdiem_requests_backup_2025_09_narok_upload.
-- Expected after: September 2025 = 6,723 rows / KES 9,495,500.
-- NOT a numbered migration - run manually in the Supabase SQL Editor.
-- The whole thing runs in one transaction; any failed check rolls it all back.

begin;

create temp table new_venues (venue_id text primary key, venue_name text, event_id text) on commit drop;

create temp table new_rows (id text primary key, participant_name text, participant_phone text, event_id text, employer text,
  transport double precision, dsa double precision, total double precision, notes text, flag_reason text) on commit drop;

-- Step 1: Safety checks.
do $$
declare n int; s double precision;
begin
  select count(*), coalesce(sum(total_perdiem), 0) into n, s from perdiem_requests where date between '2025-09-01' and '2025-09-30';
  if n <> 5066 or s <> 7698500 then
    raise exception 'September is not in the expected state: % rows / KES % (expected 5066 / 7698500) - has something already been added?', n, s;
  end if;
  if (select count(*) from new_rows) <> 1657 or (select sum(total) from new_rows) <> 1797000 then raise exception 'Row list is not 1657 / 1797000'; end if;
  if exists (select 1 from events where name = 'Narok County — TaifaCare Training - CHPs/CHAs & SCHMT') then raise exception 'A Narok event with this name already exists'; end if;
  if exists (select 1 from venues v join new_venues n on lower(v.name) = lower(n.venue_name)) then raise exception 'A Narok venue already exists'; end if;
  if exists (select 1 from perdiem_requests p join new_rows r on p.id = r.id) then raise exception 'An id already exists'; end if;
  if exists (select 1 from perdiem_requests p join new_rows r on right(p.participant_phone, 9) = right(r.participant_phone, 9)
             where p.date = '2025-09-29' and p.total_perdiem = r.total) then
    raise exception 'One of these payments is already in the system on 29 Sep 2025';
  end if;
end $$;

-- Step 2: Venues and events (one per sub-county).
select venue_id, venue_name, '', 'Narok', 0, 0 from new_venues;
                    training_start_date, training_end_date, number_of_training_days)
select event_id, '87283dbf-d590-4f66-b28d-ffe8023a1f54', 'Narok County — TaifaCare Training - CHPs/CHAs & SCHMT', now(), array['2025-09-29'], 'CHP', venue_id, venue_name, '', 'Imported (historical)', '2024-10-02', '2024-10-02', 1
from new_venues;

-- Step 3: The payments.
  id, client_id, participant_id, participant_name, participant_phone, event_id, event_name, location, date, status,
  notes, employer, other_staff, transport_allowance, dsa_allowance, total_perdiem, imported_at, flag_reason, is_overpayment, recovered_amount)
select id, '87283dbf-d590-4f66-b28d-ffe8023a1f54', null, participant_name, participant_phone, event_id, 'Narok County — TaifaCare Training - CHPs/CHAs & SCHMT', '', '2025-09-29', 'Paid',
  notes, employer, true, transport, dsa, total, now(), flag_reason, false, 0
from new_rows;

-- Step 4: Backup / undo list. Undo with:
--   delete from perdiem_requests where id in (select id from perdiem_requests_backup_2025_09_narok_upload where kind = 'payment');
--   delete from events where id in (select id from perdiem_requests_backup_2025_09_narok_upload where kind = 'event');
--   delete from venues where id in (select id from perdiem_requests_backup_2025_09_narok_upload where kind = 'venue');
create table perdiem_requests_backup_2025_09_narok_upload as
  select id, 'payment'::text as kind, total, now() as inserted_at from new_rows
  union all select event_id, 'event', null, now() from new_venues
  union all select venue_id, 'venue', null, now() from new_venues;

-- Step 5: Check before committing.
do $$
declare n int; s double precision;
begin
  select count(*), coalesce(sum(total_perdiem), 0) into n, s from perdiem_requests where date between '2025-09-01' and '2025-09-30';
  if n <> 6723 or s <> 9495500 then raise exception 'September after the upload is % rows / KES % (expected 6723 / 9495500)', n, s; end if;
end $$;

commit;

-- Step 6: Verify - expect 2025-09 = 6723 / 9495500, and 9 Narok events with 1,657 payments.
select substring(date, 1, 7) as month, count(*) as requests, sum(total_perdiem) as amount
from perdiem_requests where date between '2025-09-01' and '2025-09-30' group by 1;
select e.venue_name, count(*), sum(p.total_perdiem) from perdiem_requests p join events e on e.id = p.event_id
where e.name = 'Narok County — TaifaCare Training - CHPs/CHAs & SCHMT' group by 1 order by 1;
